const MILLISECONDS_PER_DAY = 86_400_000
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/
const CLOCK = { hour: "numeric", minute: "2-digit" }
const FORMATS = {
  time: CLOCK,
  date: { month: "short", day: "numeric" },
  "date-with-year": { month: "short", day: "numeric", year: "numeric" },
  weekday: { weekday: "long", month: "long", day: "numeric" },
  "date-time": { month: "numeric", day: "numeric", year: "2-digit", ...CLOCK },
  full: { month: "long", day: "numeric", year: "numeric", ...CLOCK, timeZoneName: "short" }
}
const relativeDays = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
const dateFormatters = new Map()

export function formatDateTime(timestamp, format = "relative", now = new Date()) {
  if (!timestamp) return

  const date = new Date(timestamp)
  if (Number.isNaN(date.getTime())) return

  // A calendar date (such as an activity heading) is not an instant. Keep its day
  // as written instead of converting midnight UTC to the viewer's timezone.
  if (DATE_ONLY.test(timestamp)) {
    const dateFormat = format === "full" ? "date-with-year" : (FORMATS[format] ? format : "date")
    return formatAbsolute(date, dateFormat, "UTC")
  }

  if (format === "relative-days") {
    return relativeDays.format(signedDifferenceInDays(now, date), "day")
  } else if (format === "relative") {
    const days = signedDifferenceInDays(now, date)
    if (days === 0) return formatAbsolute(date, "time")
    if (Math.abs(days) < 7) return relativeDays.format(days, "day")
    return formatAbsolute(date, date.getFullYear() === now.getFullYear() ? "date" : "date-with-year")
  } else {
    return formatAbsolute(date, format)
  }
}

export function signedDifferenceInDays(fromDate, toDate) {
  return (localDay(toDate) - localDay(fromDate)) / MILLISECONDS_PER_DAY
}

function localDay(date) {
  // Compare local calendar days, not elapsed hours (a DST day can be 23 or 25 hours).
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())
}

function formatAbsolute(date, format, timeZone) {
  const key = `${format}:${timeZone}`
  if (!dateFormatters.has(key)) {
    dateFormatters.set(key, new Intl.DateTimeFormat("en-US", { ...FORMATS[format], timeZone }))
  }
  return dateFormatters.get(key).format(date)
}
EOF
