import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatDateTime } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"
  static values = { card: Object }

  shareUrl() {
    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: this.hasCardValue ? this.#cardDescription() : this.bridgeElement.bridgeAttribute("share-description")
    })
  }

  #cardDescription() {
    const { addedAt, updatedAt, author, assignees } = this.cardValue
    const assignment = assignees ? `assigned to ${assignees}` : "not assigned"
    return `Added ${formatDateTime(addedAt, "date")} by ${author} and ${assignment}. Updated ${formatDateTime(updatedAt, "date")}`
  }
}
EOF
