import { Controller } from "@hotwired/stimulus"
import { put } from "@rails/request.js"

export default class extends Controller {
  static values = { settingsUrl: String, savedTimezone: String }

  connect() {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone
    document.cookie = `timezone=${encodeURIComponent(timezone)}; path=/`

    if (this.hasSettingsUrlValue && this.savedTimezoneValue !== timezone) {
      put(this.settingsUrlValue, { body: { timezone_name: timezone } })
    }
  }
}
EOF
